#nullable enable // autogenerated

using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Effects;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Projectiles;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Models;
using UnityEngine;

namespace MVZ2.GameContent.Effects
{
    [AutoEntityBehaviourDefinition(VanillaEffectNames.krakenDeathRay)]
    public class KrakenDeathRay : EntityBehaviourDefinition
    {
        public KrakenDeathRay(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            var lane = GetTargetLane(entity);
            if (lane < 0)
            {
                lane = entity.GetLane();
            }
            var column = entity.GetColumn();
            var x = entity.Level.GetEntityColumnX(column);
            var z = entity.Level.GetEntityLaneZ(lane);
            var y = entity.Level.GetGroundY(x, z);
            SetDestination(entity, new Vector3(x, y, z));
            UpdateModel(entity);
        }
        public override void Update(Entity entity)
        {
            base.Update(entity);
            var parent = entity.Parent;
            if (!parent.ExistsAndAlive())
            {
                entity.Remove();
                return;
            }

            if (entity.State != STATE_SHRINK && ShouldShrink(entity))
            {
                StartShrinkState(entity);
            }
            switch (entity.State)
            {
                case STATE_IDLE:
                    UpdateIdleState(entity);
                    break;
                case STATE_NO_TARGET:
                    UpdateNoTargetState(entity);
                    break;
            }
            UpdateModel(entity);
        }
        private void UpdateIdleState(Entity entity)
        {
            var target = entity.Target;
            if (!target.ExistsAndAlive())
            {
                target = FindNextTarget(entity);
            }
            if (target.ExistsAndAlive())
            {
                DealLaserDamage(entity, target);
                MoveDestinationTo(entity, target.GetCenter());
            }
            else
            {
                StartNoTargetState(entity);
            }
            entity.Level.ShakeScreen(5, 5, 1);
        }
        private static void UpdateNoTargetState(Entity entity)
        {
            var lane = GetTargetLane(entity);
            var dest = GetDestination(entity);
            dest.x = entity.GetMirroredX(0, false);
            dest.z = entity.Level.GetEntityLaneZ(lane);
            dest.y += LASER_MOVE_UP_SPEED;
            MoveDestinationTo(entity, dest);

            entity.Level.ShakeScreen(5, 5, 1);
        }
        private static void StartNoTargetState(Entity entity)
        {
            entity.State = STATE_NO_TARGET;

            var lane = GetTargetLane(entity);
            var dest = GetDestination(entity);
            dest.x = entity.GetMirroredX(0, false);
            dest.z = entity.Level.GetEntityLaneZ(lane);
            dest.y = entity.Level.GetGroundY(dest.x, dest.z);
            MoveDestinationTo(entity, dest);
        }
        private static void StartShrinkState(Entity entity)
        {
            entity.State = STATE_SHRINK;
            entity.Timeout = Mathf.Min(SHRINK_TIMEOUT, entity.Timeout);
        }
        public static void Shrink(Entity entity)
        {
            StartShrinkState(entity);
        }
        private Entity? FindNextTarget(Entity entity)
        {
            var dest = GetDestination(entity);
            var destX = dest.x;
            return detector.DetectEntityWithTheLeast(entity, e => (e.Position.x - destX) * entity.GetFacingX());
        }
        private static void DealLaserDamage(Entity entity, Entity target)
        {
            var damage = entity.GetDamage(true);

            var frameDamage = Mathf.Min(damage, DAMAGE_PER_FRAME);
            var remainingDamage = damage - frameDamage;

            var effects = entity.GetDamageEffectList();
            var output = target.TakeDamage(frameDamage, effects, entity);
            var overflowDamage = output.GetFinalOverflowAmount();
            if (overflowDamage > 0)
            {
                damage = remainingDamage + overflowDamage;
            }
            entity.SetDamage(damage);
        }
        private static bool ShouldShrink(Entity entity)
        {
            return entity.GetDamage(true) <= 0 || entity.Timeout <= SHRINK_TIMEOUT;
        }
        private static void MoveDestinationTo(Entity entity, Vector3 target)
        {
            var current = GetDestination(entity);
            var factor = MOVE_DESTINATION_FACTOR;
            current = current * (1 - factor) + target * factor;
            SetDestination(entity, current);
        }
        private static void UpdateModel(Entity entity)
        {
            entity.SetModelProperty("Dest", GetDestination(entity));
            entity.SetAnimationBool("Shrink", entity.State == STATE_SHRINK);
        }
        public static void SetDestination(Entity entity, Vector3 value) => entity.SetProperty(PROP_DESTINATION, value);
        public static Vector3 GetDestination(Entity entity) => entity.GetProperty<Vector3>(PROP_DESTINATION);
        public static void SetTargetLane(Entity entity, int value) => entity.SetProperty(PROP_TARGET_LANE, value);
        public static int GetTargetLane(Entity entity) => entity.GetProperty<int>(PROP_TARGET_LANE);
        public const int STATE_IDLE = VanillaEffectStates.IDLE;
        public const int STATE_NO_TARGET = VanillaEffectStates.KRAKEN_DEATH_RAY_NO_TARGET;
        public const int STATE_SHRINK = VanillaEffectStates.KRAKEN_DEATH_RAY_SHRINK;
        public const float LASER_MOVE_UP_SPEED = 10f;
        public const float MOVE_DESTINATION_FACTOR = 0.5f;
        public const float DAMAGE_PER_FRAME = 70f;
        public const int SHRINK_TIMEOUT = 5;
        public static readonly VanillaEntityPropertyMeta<int> PROP_TARGET_LANE = new VanillaEntityPropertyMeta<int>("target_lane");
        public static readonly VanillaEntityPropertyMeta<Vector3> PROP_DESTINATION = new VanillaEntityPropertyMeta<Vector3>("dest");
        private static readonly Detector detector = new RayDetector();
        public class RayDetector : Detector
        {
            protected override Bounds GetDetectionBounds(Entity self)
            {
                var lane = GetTargetLane(self);
                var destination = GetDestination(self);
                var sizeX = 8000;
                var sizeY = 40;
                var sizeZ = 40;
                var centerX = destination.x + sizeX * 0.5f * self.GetFacingX();
                var centerZ = self.Level.GetEntityLaneZ(lane);
                var centerY = self.Level.GetGroundY(destination.x, self.Position.z) + sizeY * 0.5f;
                return new Bounds(new Vector3(centerX, centerY, centerZ), new Vector3(sizeX, sizeY, sizeZ));
            }
        }
    }
}
